Point2f ConcentricSampleDisk(const Point2f &u) {
    // Map from [0,1] to [-1,1]
    Float x = 2.0f * u.x - 1.0f;
    Float y = 2.0f * u.y - 1.0f;

    // Handle the origin to avoid division by zero
    if (x == 0.0f && y == 0.0f) {
        return Point2f(0.0f, 0.0f);
    }

    // Determine the region and compute the radius and angle
    Float r, theta;
    if (std::abs(x) > std::abs(y)) {
        r = x;
        theta = (Float(M_PI) / 4.0f) * (y / x);
    } else {
        r = y;
        theta = (Float(M_PI) / 2.0f) - (Float(M_PI) / 4.0f) * (x / y);
    }

    // Map back to Cartesian coordinates
    return Point2f(r * std::cos(theta), r * std::sin(theta));
}

